from __future__ import annotations

import json
from typing import Any

STATUS = {"name": "radar_status", "description": "Local status of the radar plugin: scheduler, sources, counts. Never approves anything.", "parameters": {"type": "object", "additionalProperties": False, "properties": {}}}
LIST = {"name": "radar_list", "description": "List scheduler timers (follow-ups) of the current scope.", "parameters": {"type": "object", "additionalProperties": False, "properties": {"limit": {"type": "integer", "minimum": 1, "maximum": 100}}}}
INSPECT = {"name": "radar_inspect", "description": "Inspect one local radar object by id (task, signal, proposal, job, source...). Read-only.", "parameters": {"type": "object", "additionalProperties": False, "required": ["id"], "properties": {"id": {"type": "string"}}}}
PROPOSE = {"name": "radar_propose", "description": "Create an immutable read-only plan for an existing follow-up when policy validates operation, source, resource and grant. Never grants consent nor executes changes.", "parameters": {"type": "object", "additionalProperties": False, "required": ["operation_id", "parameters", "followup_id", "source_id"], "properties": {"operation_id": {"type": "string"}, "parameters": {"type": "object"}, "followup_id": {"type": "string"}, "source_id": {"type": "string"}}}}
TASKS = {"name": "radar_tasks", "description": "List the owner's tracked tasks (trips, purchases, work items, commitments) with their pending proposals. Use it to answer 'what is pending' or before resolving a proposal.", "parameters": {"type": "object", "additionalProperties": False, "properties": {"status": {"type": "string", "enum": ["open", "all", "closed"]}, "limit": {"type": "integer", "minimum": 1, "maximum": 100}}}}
TASK = {"name": "radar_task", "description": "Act on one tracked radar task the way the owner would from a notice. This is the ONLY way to change a task; never edit radar's database or files directly. Actions: 'wait' parks the task until `until` (ISO 8601 moment, e.g. 2026-11-25T08:00:00Z) because the owner waits for someone else to move (use it when the owner says to wait until they answer, or that they already asked and will see); 'later' snoozes it until tomorrow morning, or until `until` when the owner names a moment to be reminded at (remind me on December 10, Friday at nine: pass that moment in their local time, as YYYY-MM-DD or YYYY-MM-DDTHH:MM); 'mute' stops every notice about it for good (use it when the owner says to stop telling them about this, or to ignore it); 'unmute' lifts that; 'done' records the owner saying it is resolved; 'reopen' brings a closed, parked or muted task back. Find the task id with radar_tasks (a prefix of the id is enough). Record a single decision on one step with radar_resolve instead.", "parameters": {"type": "object", "additionalProperties": False, "required": ["task_id", "action"], "properties": {"task_id": {"type": "string"}, "action": {"type": "string", "enum": ["wait", "later", "mute", "unmute", "done", "reopen"]}, "until": {"type": "string", "description": "For 'wait': the ISO 8601 moment to wake the task up. For 'later': the moment the owner named, in their local time; omit it for a plain later."}, "note": {"type": "string", "description": "The owner's words, for the record."}}}}
RESOLVE = {"name": "radar_resolve", "description": "Record the owner's decision on a pending radar proposal (accept, decline, later, done). Accepting a read/local proposal queues the work as a bounded job; external actions still require explicit consent.", "parameters": {"type": "object", "additionalProperties": False, "required": ["proposal_id", "decision"], "properties": {"proposal_id": {"type": "string"}, "decision": {"type": "string", "enum": ["accept", "decline", "later", "done"]}, "note": {"type": "string"}}}}
PREFERENCE = {"name": "radar_preference", "description": "Save a lasting attention preference the owner stated in the conversation (never notify about a sender, only summarise CI alerts, always interrupt for a project...). Scope it as narrowly as the owner meant: sender (email address), account (mailbox), kind (trip, purchase, work_item, commitment, check, routine, other), source_kind (email, session_turn, github, calendar), project or repo; leave the scope empty for a general rule. effect: silent, digest, notify or prefer. exceptions: risk flags that still break through (security, service_interruption, deadline, financial_loss).", "parameters": {"type": "object", "additionalProperties": False, "required": ["instruction", "effect"], "properties": {"instruction": {"type": "string"}, "effect": {"type": "string", "enum": ["silent", "digest", "notify", "prefer"]}, "dimension": {"type": "string", "enum": ["notification", "investigation", "response"]}, "scope": {"type": "object", "additionalProperties": False, "properties": {key: {"type": "string"} for key in ("account", "sender", "message_type", "project", "kind", "source_kind", "repo")}}, "exceptions": {"type": "array", "items": {"type": "string", "enum": ["security", "service_interruption", "deadline", "financial_loss"]}}, "task_id": {"type": "string"}}}}
EXPLAIN = {"name": "radar_explain", "description": "Explain one tracked task: evidence signals, checklist, proposals and jobs. Optionally writes a standalone HTML report and returns its path.", "parameters": {"type": "object", "additionalProperties": False, "required": ["task_id"], "properties": {"task_id": {"type": "string"}, "html": {"type": "boolean"}}}}


def as_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)
